            .statusCode(422)
            .body("error", is("CAPACITY_EXCEEDED"));
    }

    private static DataSource createTestDataSource() {
        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada_test");
